+import assert from 'node:assert/strict';
+import { after, before, describe, it } from 'node:test';
+import { parseCsvRecords, parseImportCsv } from '../src/lib/csv.ts';
+import { api, startTestServer, type TestServer } from './helpers.ts';
+
+const HEADER = 'tracking,carrier,service,name,street,zip,city,country,phone';
+
+describe('CSV import with quoted cells', () => {
+  it('keeps a comma inside quotes in one cell', () => {
+    const [row] = parseImportCsv(`${HEADER}\nRR987654326AT,OEPOST,standard,"Müller, Hans",Herrengasse 12,8010,Graz,AT,+43 1`);
+    assert.equal(row.recipient.name, 'Müller, Hans');
+    assert.equal(row.recipient.street, 'Herrengasse 12');
+    assert.equal(row.recipient.zip, '8010');
+    assert.equal(row.recipient.phone, '+43 1');
+  });
+
+  it('handles escaped quotes, embedded line breaks and CRLF', () => {
+    assert.deepEqual(parseCsvRecords('a,"say ""hi""",c\r\n"x\ny",,z\r\n\r\n'), [
+      ['a', 'say "hi"', 'c'],
+      ['x\ny', '', 'z'],
+    ]);
+  });
+
+  it('still parses unquoted input like before', () => {
+    const rows = parseImportCsv(`${HEADER}\n00340434161094042557,DPDAT,express,Lukas Berger,Herrengasse 12,8010,Graz,AT,`);
+    assert.equal(rows[0].carrier, 'DPD');
+    assert.equal(rows[0].recipient.phone, undefined);
+  });
+
+  describe('POST /import', () => {
+    let srv: TestServer;
+    before(async () => { srv = await startTestServer(); });
+    after(async () => { await srv.close(); });
+
+    it('imports a row whose recipient name contains a comma', async () => {
+      const csv = `${HEADER}\nRR987654326AT,OEPOST,standard,"Müller, Hans",Herrengasse 12,8010,Graz,AT,\n`;
+      const res = await api(srv.url, 'POST', '/import', csv);
+      assert.deepEqual(res.body, { created: 1, errors: [] });
+      const saved = srv.store.findByTrackingNumber('RR987654326AT');
+      assert.equal(saved?.recipient.name, 'Müller, Hans');
+      assert.equal(saved?.recipient.zip, '8010');
+    });
+  });
+});
